==================================================================
#define _GNU_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/prctl.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef N_SLIP
#define N_SLIP 1
#endif
#ifndef TIOCSETD
#define TIOCSETD 0x5423
#endif
#ifndef TIOCSTI
#define TIOCSTI 0x5412
#endif
#ifndef TIOCVHANGUP
#define TIOCVHANGUP 0x5437
#endif

#define T1_HEAD_START_US 30000

static char g_marker[16] = "syzrepro";
static int g_fd = -1;

static void set_thread_name(int idx)
{
	char nm[16];

	snprintf(nm, sizeof(nm), "%s%d", g_marker, idx);
	nm[15] = '\0';
	if (prctl(PR_SET_NAME, nm, 0, 0, 0) != 0)
		printf("repro: prctl(PR_SET_NAME, %s) failed: %s\n",
		       nm, strerror(errno));
}

static void *thread_use(void *arg)
{
	unsigned char ch = 0x40;
	int r;

	(void)arg;
	set_thread_name(0);

	r = ioctl(g_fd, TIOCSTI, &ch);
	if (r != 0)
		printf("repro: T0 TIOCSTI -> %d (%s)\n", r, strerror(errno));
	return NULL;
}

static void *thread_free(void *arg)
{
	int r;

	(void)arg;
	set_thread_name(1);

	usleep(T1_HEAD_START_US);

	r = ioctl(g_fd, TIOCVHANGUP, 0);
	if (r != 0)
		printf("repro: T1 TIOCVHANGUP -> %d (%s)\n", r, strerror(errno));
	return NULL;
}

int main(void)
{
	int iters = 10;
	int i;

	setvbuf(stdout, NULL, _IONBF, 0);


	for (i = 0; i < iters; i++) {
		int fd, ldisc = N_SLIP;
		pthread_t t0, t1;

		fd = open("/dev/ptmx", O_RDWR | O_NOCTTY);
		if (fd < 0) {
			usleep(200000);
			continue;
		}

		if (ioctl(fd, TIOCSETD, &ldisc) != 0) {
			close(fd);
			usleep(200000);
			continue;
		}

		g_fd = fd;

		if (pthread_create(&t0, NULL, thread_use, NULL) != 0) {
			close(fd);
			continue;
		}
		if (pthread_create(&t1, NULL, thread_free, NULL) != 0) {
			pthread_join(t0, NULL);
			close(fd);
			continue;
		}

		pthread_join(t0, NULL);
		pthread_join(t1, NULL);

		g_fd = -1;
		close(fd);
	}

	return 0;
}
