+	if (!IS_COMPRESS_CACHE(cache))
+		entry->next_entry = NULL;
+	else
+		entry->ino = 0;
 	INIT_LIST_HEAD(&entry->list);
 
 	entry->cache = cache;
@@ -620,6 +623,10 @@ unsigned long f2fs_shrink_cache(struct f2fs_sb_info *sbi,
